insert into public.pattern_contents(pattern_id, pkg, updated_at) select id, '{"app": "knitup-pattern-package", "ver": 1, "title": "페어아일 요크 스웨터", "level": 4, "meta": {"실": "울 DK 바탕 400g · 배색 4색 각 50g", "바늘": "대바늘 3.5mm · 4.0mm 줄바늘", "난이도": "상급 (4단계)"}, "notes": ["탑다운: 목에서 시작해 요크를 4번 늘리고 배색 무늬를 넣어요(여기는 요크 차트만).", "요크 뒤 몸통·소매는 겉뜨기 원통 — 가슴둘레 86~122cm 5사이즈는 코 수 표 참고.", "뒷목은 숏로우 6단으로 높여요."], "techs": ["K16", "K20", "K23", "K24", "K28"], "charts": [{"kind": "round", "part": "요크 (배색)", "yarn": {"name": "네이비 바탕 · 머스터드·레드·크림 배색", "color": "#2f3e5c"}, "graph": null, "instr": [{"no": "시작", "cnt": "", "text": "원통 코잡기 120코 (3.5mm)"}, {"no": "1단", "cnt": "총 120코", "text": "(겉 1, 안 1) ×60 — 목 고무단"}, {"no": "2단", "cnt": "총 120코", "text": "(겉 1, 안 1) ×60 — 목 고무단"}, {"no": "3단", "cnt": "총 120코", "text": "(겉 1, 안 1) ×60 — 목 고무단"}, {"no": "4단", "cnt": "총 120코", "text": "(겉 1, 안 1) ×60 — 목 고무단"}, {"no": "5단", "cnt": "총 120코", "text": "(겉 1, 안 1) ×60 — 목 고무단"}, {"no": "6단", "cnt": "총 120코", "text": "(겉 1, 안 1) ×60 — 목 고무단"}, {"no": "7단", "cnt": "총 120코", "text": "배색 차트 1단 — 바탕·무늬색 번갈아 겉뜨기 120코"}, {"no": "8단", "cnt": "총 120코", "text": "배색 차트 2단 — 바탕·무늬색 번갈아 겉뜨기 120코"}, {"no": "9단", "cnt": "총 120코", "text": "배색 차트 3단 — 바탕·무늬색 번갈아 겉뜨기 120코"}, {"no": "10단", "cnt": "총 160코", "text": "(겉 2, 늘리기) ×40 → 160코 — 요크 늘리기"}, {"no": "11단", "cnt": "총 160코", "text": "배색 차트 5단 — 바탕·무늬색 번갈아 겉뜨기 160코"}, {"no": "12단", "cnt": "총 160코", "text": "배색 차트 6단 — 바탕·무늬색 번갈아 겉뜨기 160코"}, {"no": "13단", "cnt": "총 160코", "text": "배색 차트 7단 — 바탕·무늬색 번갈아 겉뜨기 160코"}, {"no": "14단", "cnt": "총 160코", "text": "배색 차트 8단 — 바탕·무늬색 번갈아 겉뜨기 160코"}, {"no": "15단", "cnt": "총 160코", "text": "배색 차트 9단 — 바탕·무늬색 번갈아 겉뜨기 160코"}, {"no": "16단", "cnt": "총 200코", "text": "(겉 3, 늘리기) ×40 → 200코 — 요크 늘리기"}, {"no": "17단", "cnt": "총 200코", "text": "배색 차트 11단 — 바탕·무늬색 번갈아 겉뜨기 200코"}, {"no": "18단", "cnt": "총 200코", "text": "배색 차트 12단 — 바탕·무늬색 번갈아 겉뜨기 200코"}, {"no": "19단", "cnt": "총 200코", "text": "배색 차트 13단 — 바탕·무늬색 번갈아 겉뜨기 200코"}, {"no": "20단", "cnt":